"""ORION XML INVOIC (GRiT ORION, versions 3.0.x – 3.1.3): structure checks and mapping to EN 16931."""
from __future__ import annotations

import json
from functools import lru_cache

from lxml import etree

from ..resources import data_path


@lru_cache(maxsize=1)
def mapping() -> dict:
    """data/mappings/orion_invoic.json (generated by tools/import_orion.py) + lookup indexes."""
    mp = json.loads(data_path("mappings", "orion_invoic.json").read_text(encoding="utf-8"))
    mp["by_id"] = {f["id"]: f for f in mp["fields"] if f["id"]}
    mp["by_path"] = {f["path"]: f for f in mp["fields"]}
    mp["containers_by_path"] = {c["path"]: c for c in mp["containers"]}
    return mp


def parse(data: bytes) -> etree._Element:
    return etree.fromstring(data, etree.XMLParser(resolve_entities=False, no_network=True, huge_tree=False))


def text(el) -> str | None:
    """Element text; empty elements (<x/>, <x></x>, whitespace) count as absent – ORION senders emit them freely."""
    if el is None:
        return None
    return (el.text or "").strip() or None


def rel_path(el) -> str:
    """'body/message_header/party/party_id' – element path under <orion_message>, without positions."""
    parts = []
    while el is not None and el.getparent() is not None:
        parts.append(etree.QName(el).localname)
        el = el.getparent()
    return "/".join(reversed(parts))


def where(el) -> str:
    """'body/message_header/party[4]/party_name' – positional path for the report."""
    p = el.getroottree().getpath(el)
    return p.split("/", 2)[2] if p.count("/") >= 2 else p


def version_key(v: str | None) -> tuple:
    try:
        return tuple(int(x) for x in (v or "").split("."))
    except ValueError:
        return ()
